def _b04_siren(name):
    'The (H0, upper error, lower error) tuple of one GW170817 analysis, as typed in verify_iams_law_derivations.py.'
    m = re.search(r'\("%s", ([\d.]+), ([\d.]+), ([\d.]+)\)' % re.escape(name), file_text('docs/verification/scripts/verify_iams_law_derivations.py'))
    return tuple(float(x) for x in m.groups())

def _b04_weff(a):
    'w_eff = -1 - (1/(3a)) rho_info/(rho_Lambda + rho_info), rho_info = beta_m E(a), rho_Lambda = 1 - Omega_m (units of the critical density today).'
    E = float(E_act(a))
    return -1 - (1 / (3 * a)) * beta_m * E / ((1 - Om) + beta_m * E)

# helpers of the part2/p2_22b_higgs_record checks
def _b07_hr_t(T_GeV, gs=106.75):
    # t = 0.301 g*^(-1/2) m_P / T^2 in seconds; m_P = 1.220890e19 GeV (CODATA 2018), hbar = 6.582119569e-25 GeV s (CODATA 2018)
    mP_GeV = 1.220890e19; hbar_GeVs = 6.582119569e-25
    coef = 1 / (2 * math.sqrt(4 * math.pi**3 / 45))   # t = 1/(2H), H = sqrt(4 pi^3 g*/45) T^2/m_P (radiation era)
    return coef * gs**-0.5 * mP_GeV / T_GeV**2 * hbar_GeVs

def _b07_hr_fH():
    # Hubble rate at T_c = 159.5 GeV redshifted to today (book line 110): a_EW H(T_c)/hbar, a_EW from entropy conservation
    hbar_GeVs = 6.582119569e-25; mP_GeV = 1.220890e19
    Tc = 159.5; gs = 106.75; gs0 = 2 + 7 / 8 * 2 * 3.046 * 4 / 11
    a_EW = (gs0 / gs) ** (1 / 3) * (kB * T_CMB / e_ch / 1e9) / Tc
    H_GeV = math.sqrt(4 * math.pi**3 / 45) * gs**0.5 * Tc**2 / mP_GeV
    return a_EW * H_GeV / hbar_GeVs

# helpers of the part2/p2_15a_lepton_koide checks
# Koide helpers: masses in MeV. m_e from CODATA 2018 m_e (kg) and c, e (SI exact); m_mu from CODATA 2018 m_mu/m_e = 206.7682830;
# m_tau = 1776.93 +- 0.09 MeV (PDG 2024, doi:10.1103/PhysRevD.110.030001).
_B07_ME = m_e * c**2 / e_ch / 1e6
_B07_MMU = 206.7682830 * _B07_ME
_B07_MTAU24, _B07_STAU24 = 1776.93, 0.09
def _b07_Q(a, b, cc):
    return (a + b + cc) / (math.sqrt(a) + math.sqrt(b) + math.sqrt(cc))**2
def _b07_delta(mt):
    s = [math.sqrt(mt), math.sqrt(_B07_ME), math.sqrt(_B07_MMU)]
    x = sum(s) / 3; r = math.sqrt(2 * (3 * _b07_Q(_B07_ME, _B07_MMU, mt) - 1))
    return math.acos((s[0] / x - 1) / r)
def _b07_mtau_exact():
    # m_tau fixed by Q = 2/3 exactly: solve Q(m_e, m_mu, m_tau) = 2/3 for the heavy root
    return brentq(lambda mt: _b07_Q(_B07_ME, _B07_MMU, mt) - 2 / 3, 1500.0, 2000.0, xtol=1e-12)

# helpers of the part2/p2_15b_electron_mass checks
def _b07_em_B(H0):
    # the bracket B = [hbar H0 ln2 m_P^(3/2) / (alpha^(5/2) c^2)]^(2/5), kg (Eq. eq:em:mstar); CODATA 2018 constants
    return (hbar * Hsi(H0) * LN2 * mP**1.5 / (alpha_em**2.5 * c**2))**0.4
def _b07_em_fp(H0):
    # fixed point with the identified factor, units of m_e (Eq. eq:em:result)
    return (2 * math.pi)**-0.1 * _b07_em_B(H0) / m_e
