@check(label='ch:virial:L181:4.25\\%', chapter='ch:virial', part=2, title='fsigma8 deficit today vs LCDM growth ODE',
       file='part2/p2_02_virial', line=181, status='calc', kind='num', printed='4.25\\%', tol=0.00118)
def check_0298():
    'fsigma8 deficit today vs LCDM growth ODE. Book line 181, printed 4.25\\%.'
    import numpy as np; from scipy.integrate import solve_ivp; pass; OL=1-Om; bm=beta_m
    def E2(a): return Om*a**-3+OL
    def Eo(a): return np.exp(1-1/a)
    def rhs(N,y,on):
     a=np.exp(N); d,dd=y; H2=E2(a); dlnH=-1.5*Om*a**-3/H2
     mu=H2/(H2+bm*Eo(a)) if on else 1.0
     return [dd, -(2+dlnH)*dd+1.5*Om*a**-3*mu/H2*d]
    N0,N1=np.log(1e-3),0.0; y0=[1e-3,1e-3]
    sl=solve_ivp(rhs,[N0,N1],y0,args=(False,),rtol=1e-9); si=solve_ivp(rhs,[N0,N1],y0,args=(True,),rtol=1e-9)
    dl,ddl=sl.y[:,-1]; di,ddi=si.y[:,-1]
    value = 1-(ddi/di*di)/(ddl/dl*dl)
    return locals()

@check(label='ch:virial:L181:0', chapter='ch:virial', part=2, title='E(a) -> 0 at early times',
       file='part2/p2_02_virial', line=181, status='derived', kind='num', printed='0', tol=0.0)
def check_3203():
    'Limit of E(a) = exp(1 - 1/a) as a -> 0+ (sympy). Book line 181 (caption), printed 0.'
    a = sp.symbols('a', positive=True)
