    rhs = 1
    Psi_n = -4 * sp.Rational(105, 100) * sp.pi * G_ * a**2 * rho * dl / k**2
    neg_lhs = sp.solve(sp.Eq(k**2 * (Psi_n + Psi_n), -8 * sp.pi * G_ * Sg * a**2 * rho * dl), Sg)[0]
    return locals()

