@check(label='ch:theory:L582', chapter='ch:theory', part=2, title='least-squares w0 repeat',
       file='part2/p2_03_theory', line=582, status='none', kind='num', printed='-1.065', tol=0.00047)
def check_0459():
    'least-squares w0 repeat. Book line 582, printed -1.065.'
    Omc=0.315; OLc=1-Omc; bmc=Omc/2
    def w_eff(a): Ea=E_act(a); wi=-1-1/(3*a); return (-OLc+bmc*Ea*wi)/(OLc+bmc*Ea)
    avals=np.linspace(0.5,1,200); yvals=np.array([w_eff(a) for a in avals])
    Avec=np.vstack([np.ones_like(avals),1-avals]).T
    coef,_,_,_=np.linalg.lstsq(Avec,yvals,rcond=None)
    value=coef[0]
    return locals()

