@check(label='eq:th:D2', chapter='ch:theory', part=2, title='second-order growth eqn + Friedmann matter-density identity',
       file='part2/p2_03_theory', line=812, status='derived', kind='sym', printed='', tol=0.0)
def check_0485():
    'second-order growth eqn + Friedmann matter-density identity (Eq. eq:th:D2). Book line 812.'
    G,H0,Om,a=sp.symbols('G H0 Om a',positive=True)
    rho_bar_m=Om*(3*H0**2/(8*sp.pi*G))*a**-3
    lhs=4*sp.pi*G*rho_bar_m
    rhs=sp.Rational(3,2)*H0**2*Om*a**-3
    return locals()

@check(label='ch:theory:L814', chapter='ch:theory', part=2, title='EdS trial-solution coefficient for D2 initial condition',
       file='part2/p2_03_theory', line=814, status='derived', kind='sym', printed='-3/7', tol=0.0)
def check_0486():
    'EdS trial-solution coefficient for D2 initial condition. Book line 814, printed -3/7.'
    t,c=sp.symbols('t c',positive=False)
    D1=t**sp.Rational(2,3)
    H=sp.Rational(2,3)/t
    fpGrho=2/(3*t**2)
    D2=c*t**sp.Rational(4,3)
    sol=sp.solve(sp.Eq(sp.diff(D2,t,2)+2*H*sp.diff(D2,t)-fpGrho*D2,-fpGrho*D1**2),c)[0]
    lhs=sol
    rhs=sp.Rational(-3,7)
    return locals()

