@check(label='eq:th:Meq', chapter='ch:theory', part=2, title='equilibrium mass from setting T_BH=T_GH',
       file='part2/p2_03_theory', line=951, status='derived', kind='sym', printed='', tol=0.0)
def check_0511():
    'equilibrium mass from setting T_BH=T_GH (Eq. eq:th:Meq). Book line 951.'
    G_,M_,hbar_,c_,kB_,H_=sp.symbols('G M hbar c kB H',positive=True)
    TBH=hbar_*c_**3/(8*sp.pi*G_*M_*kB_)
    TGH=hbar_*H_/(2*sp.pi*kB_)
    Msol=sp.solve(sp.Eq(TBH,TGH),M_)[0]
    lhs=Msol
    rhs=c_**3/(4*G_*H_)
    return locals()

