@check(label='eq:th:Gamma', chapter='ch:theory', part=2, title='thermally limited bit-encoding rate from Hawking power',
       file='part2/p2_03_theory', line=956, status='derived', kind='sym', printed='', tol=0.0)
def check_0513():
    'thermally limited bit-encoding rate from Hawking power (Eq. eq:th:Gamma). Book line 956.'
    G_,M_,hbar_,c_,kB_=sp.symbols('G M hbar c kB',positive=True)
    P=hbar_*c_**6/(15360*sp.pi*G_**2*M_**2)
    TBH=hbar_*c_**3/(8*sp.pi*G_*M_*kB_)
    ln2=sp.log(2)
    lhs=P/(kB_*TBH*ln2)
    rhs=c_**3/(1920*G_*M_*ln2)
    return locals()

@check(label='ch:theory:L1042', chapter='ch:theory', part=2, title='drafted check, screened (runs; negative control fails)',
       file='part2/p2_03_theory', line=1042, status='calc', kind='num', printed='2.8\\%', tol=0.0)
def check_0514():
    'drafted check, screened (runs; negative control fails). Book line 1042, printed 2.8\\%.'
    # Line 1042: "MGCAMB parameterisation equals the exact form at z=0 and is within 2.8% at all z"
    # This is the maximum per cent difference between mu_mgcamb(a) and mu_iam(a) over all redshift.
    # Search for the z (or a) where |mu_mgcamb - mu_iam| / |mu_iam| is largest.

    a_vals = np.linspace(0.001, 1.0, 10000)
    mu_exact = np.array([mu_iam(a) for a in a_vals])
    mu_mgcamb_vals = np.array([mu_mgcamb(a) for a in a_vals])
    pct_diff = 100 * np.abs(mu_mgcamb_vals - mu_exact) / np.abs(mu_exact)
    value = float(np.max(pct_diff))
    return locals()

@check(label='ch:theory:L1042:0.65', chapter='ch:theory', part=2, title='drafted check, screened (runs; negative control fails)',
       file='part2/p2_03_theory', line=1042, status='calc', kind='num', printed='0.65', tol=0.0)
def check_0515():
    'drafted check, screened (runs; negative control fails). Book line 1042, printed 0.65.'
    # Line 1042: "largest near z≈0.65"
    # Find the redshift where the per cent difference between mu_mgcamb and mu_iam is maximum.

    a_vals = np.linspace(0.001, 1.0, 10000)
    mu_exact = np.array([mu_iam(a) for a in a_vals])
    mu_mgcamb_vals = np.array([mu_mgcamb(a) for a in a_vals])
    pct_diff = 100 * np.abs(mu_mgcamb_vals - mu_exact) / np.abs(mu_exact)
    idx_max = np.argmax(pct_diff)
    a_max = a_vals[idx_max]
    z_max = 1.0 / a_max - 1.0
    value = float(z_max)
    return locals()

