@check(label='ch:entropicgravity:L176', chapter='ch:entropicgravity', part=2, title='redshift of peak dE/dt rate',
       file='part2/p2_03a_entropic_gravity', line=176, status='calc', kind='num', printed='1.26', tol=0.00397)
def check_0556():
    'redshift of peak dE/dt rate. Book line 176, printed 1.26.'
