@check(label="ch:sectortension:L31:0.1'", chapter='ch:sectortension', part=2, title='fsigma8 deficit at QSO redshift z=1.491',
       file='part2/p2_09_sector_tension', line=31, status='calc', kind='num', printed='0.1', tol=0.5)
def check_0926():
    'fsigma8 deficit at QSO redshift z=1.491. Book line 31, printed 0.1.'
    pass;OL=1-Om;bm=beta_m;import numpy as np;from scipy.integrate import solve_ivp;E=lambda a:np.exp(1-1/a);H2=lambda a:Om*a**-3+OL
    def rhs(N,y,on):
     a=np.exp(N);h2=H2(a);dlnH2=-3*Om*a**-3/h2;D,Dp=y;mu=h2/(h2+bm*E(a)) if on else 1.0;return [Dp,-(2+0.5*dlnH2)*Dp+1.5*Om*a**-3/h2*mu*D]
    Ni=np.log(1e-3);z=1.491;Nq=np.log(1/(1+z))
    s0=solve_ivp(rhs,[Ni,Nq],[np.exp(Ni)]*2,args=(False,),rtol=1e-9,atol=1e-12);s1=solve_ivp(rhs,[Ni,Nq],[np.exp(Ni)]*2,args=(True,),rtol=1e-9,atol=1e-12)
    D0,Dp0=s0.y[:,-1];D1,Dp1=s1.y[:,-1];f0=Dp0/D0;f1=Dp1/D1;value=100*(1-(f1*D1)/(f0*D0))
    return locals()

@check(label='ch:sectortension:L31:2.2', chapter='ch:sectortension', part=2, title='fsigma8 deficit at BGS redshift z=0.295',
       file='part2/p2_09_sector_tension', line=31, status='calc', kind='num', printed='2.2', tol=0.0227)
def check_0927():
    'fsigma8 deficit at BGS redshift z=0.295. Book line 31, printed 2.2.'
    pass;OL=1-Om;bm=beta_m;import numpy as np;from scipy.integrate import solve_ivp;E=lambda a:np.exp(1-1/a);H2=lambda a:Om*a**-3+OL
    def rhs(N,y,on):
     a=np.exp(N);h2=H2(a);dlnH2=-3*Om*a**-3/h2;D,Dp=y;mu=h2/(h2+bm*E(a)) if on else 1.0;return [Dp,-(2+0.5*dlnH2)*Dp+1.5*Om*a**-3/h2*mu*D]
    Ni=np.log(1e-3);z=0.295;Nq=np.log(1/(1+z))
    s0=solve_ivp(rhs,[Ni,Nq],[np.exp(Ni)]*2,args=(False,),rtol=1e-9,atol=1e-12);s1=solve_ivp(rhs,[Ni,Nq],[np.exp(Ni)]*2,args=(True,),rtol=1e-9,atol=1e-12)
    D0,Dp0=s0.y[:,-1];D1,Dp1=s1.y[:,-1];f0=Dp0/D0;f1=Dp1/D1;value=100*(1-(f1*D1)/(f0*D0))
    return locals()

