@check(label='ch:dsvalidation:L67', chapter='ch:dsvalidation', part=2, title='activation function E(1)=1 check',
       file='part2/p2_10_dual_sector_validation', line=67, status='derived', kind='sym', printed='', tol=0.0)
def check_1061():
    'activation function E(1)=1 check. Book line 67.'
    a=sp.symbols('a',positive=True)
    E=sp.exp(1-1/a)
    lhs=E.subs(a,1); rhs=sp.Integer(1)
    ok=sp.simplify(lhs-rhs)==0
    return locals()

@check(label='ch:dsvalidation:L67:3', chapter='ch:dsvalidation', part=2, title='inflection of E(a) at a=1/2',
       file='part2/p2_10_dual_sector_validation', line=67, status='derived', kind='sym', printed='', tol=0.0)
def check_1062():
    'inflection of E(a) at a=1/2. Book line 67.'
    a=sp.symbols('a',positive=True)
    E=sp.exp(1-1/a)
    d2=sp.diff(E,a,2)
    ok=sp.simplify(d2.subs(a,sp.Rational(1,2)))==0
    return locals()

@check(label='ch:dsvalidation:L67:4', chapter='ch:dsvalidation', part=2, title='maximum of dE/dlna at a=1',
       file='part2/p2_10_dual_sector_validation', line=67, status='derived', kind='sym', printed='', tol=0.0)
def check_1063():
    'maximum of dE/dlna at a=1. Book line 67.'
    a=sp.symbols('a',positive=True)
    E=sp.exp(1-1/a)
    g=sp.diff(E,a)*a
    dg=sp.diff(g,a); d2g=sp.diff(g,a,2)
    ok=(sp.simplify(dg.subs(a,1))==0) and (d2g.subs(a,1)<0)
    return locals()

