@check(label='ch:surveys:L98', chapter='ch:surveys', part=2, title='drafted check, screened (runs; negative control fails)',
       file='part2/p2_16_survey_predictions', line=98, status='calc', kind='num', printed='0.229', tol=0.0)
def check_1569():
    'drafted check, screened (runs; negative control fails). Book line 98, printed 0.229.'
    # Line 98: |dμ/dz| at z=0, largest value
    # μ(a) = H²/(H² + β_m E(a) H₀²)
    # dμ/dz = dμ/da · da/dz, with da/dz = -a/(1+z)
    a_z0 = 1.0
    H2_0 = H2_lcdm(a_z0)
    E_0 = E_act(a_z0)
    # dμ/da at a=1
    eps = 1e-8
    mu_plus = mu_iam(a_z0 + eps)
    mu_minus = mu_iam(a_z0 - eps)
    dmu_da = (mu_plus - mu_minus) / (2 * eps)
    # da/dz at z=0: da/dz = -a/(1+z)
    da_dz_z0 = -a_z0 / 1.0
    dmu_dz_z0 = dmu_da * da_dz_z0
    value = abs(dmu_dz_z0)
    return locals()

