@check(label='ch:surveys:L160:7.5', chapter='ch:surveys', part=2, title='drafted check, screened (runs; negative control fails)',
       file='part2/p2_16_survey_predictions', line=160, status='calc', kind='num', printed='7.5', tol=0.0)
def check_1581():
    'drafted check, screened (runs; negative control fails). Book line 160, printed 7.5.'
    # Line 160: "Its error is 7.5 times the predicted shift of 0.008"
    # The measurement error is 0.06 (from E_G = 0.39 ± 0.06)
    # The predicted shift at z=0.32 is given on line 159 as "+1.8% at z=0.3"
    # Predicted shift in E_G: 1.8% of what value?
    # E_G GR = Omega_m0 / f_gr at z=0.32
    # The shift is the difference between IAM and GR at this redshift

    z_eg = 0.32
    f_gr = f_of("lcdm", z_eg)
    f_iam_z = f_of("iam", z_eg)
    Omega_m0 = Om

    E_G_gr = Omega_m0 / f_gr
    E_G_iam = Omega_m0 / f_iam_z
    delta_EG = E_G_iam - E_G_gr

    measurement_error = 0.06
    ratio = measurement_error / delta_EG
    value = ratio
    return locals()

