    hb,c_,G_,kap,eta=sp.symbols('hbar c G kappa eta',positive=True)
    eta_s=sp.solve(sp.Eq(hb*eta/(2*sp.pi), c_**3/(8*sp.pi*G_)), eta)[0]  # from the structural identity
    dA=(8*sp.pi*G_/(kap*c_**2))*(hb*kap/(2*sp.pi*c_))  # first law dA = 8 pi G dM c^2/(kappa c^4) with one Unruh quantum hbar kappa/(2 pi c)
