@check(label='ch:higgsrecord:L67', chapter='ch:higgsrecord', part=4, title='drafted check, screened (runs; negative control fails)',
       file='part2/p2_22b_higgs_record', line=67, status='calc', kind='num', printed='1.77', tol=0.0)
def check_2114():
    'drafted check, screened (runs; negative control fails). Book line 67, printed 1.77.'
    # Line 67: "E=0.17 falls at z=1.77"
    # Given: E(a) = exp(1 - 1/a), solve for z when E = 0.17
    # Relationship: z = 1/a - 1, so a = 1/(1+z)

    target_E = 0.17
    # E = exp(1 - 1/a) = 0.17
    # 1 - 1/a = ln(0.17)
    # 1/a = 1 - ln(0.17)
    # a = 1 / (1 - ln(0.17))

    a_solution = 1.0 / (1.0 - math.log(target_E))
    z_solution = 1.0 / a_solution - 1.0

    value = z_solution
    return locals()

@check(label='ch:higgsrecord:L67:3.67', chapter='ch:higgsrecord', part=4, title='cosmic age at z=1.77, Gyr (Planck 2018 LCDM)',
       file='part2/p2_22b_higgs_record', line=67, status='calc', kind='num', printed='3.67', tol=0)
def check_2115():
    'cosmic age at z=1.77, Gyr (Planck 2018 LCDM). Book line 67, printed 3.67.'
    Orad=9.1e-5  # Planck 2018 radiation density (photons + 3 massless neutrinos)
    def age(z, H0=67.36): return quad(lambda x: 1/((1+x)*math.sqrt(Om*(1+x)**3+Orad*(1+x)**4+1-Om-Orad)), z, np.inf)[0]/Hsi(H0)/Gyr  # Planck 2018 LCDM H0 67.36
    value=age(1.77)
    return locals()

