@check(label='ch:temperature:L5', chapter='ch:temperature', part=6, title='M at 10 C',
       file='part4/p4_10_temperature', line=5, status='calc', kind='num', printed='22.94', tol=0)
def check_2534():
    'M at 10 C. Book line 5, printed 22.94.'
    Mt=lambda TC: dG_ATP/(R_gas*(TC+273.15))
    EJ=E_hold*kB*T_cell  # holding energy held fixed in joules
    e0=lambda TC: 1/(1+math.exp(EJ/(kB*(TC+273.15))))
    Hb=lambda e: -(e*math.log2(e)+(1-e)*math.log2(1-e))
    fl=lambda TC: Hb(e0(TC))/Hb(e0(37))
    value=Mt(10)
    return locals()

