# ======== Part 7 | ch:onegauge | docs/book/part3/p3_08_one_gauge.tex
@check(label='ch:onegauge:L22', chapter='ch:onegauge', part=7, title='drafted check, screened (runs; negative control fails)',
       file='part3/p3_08_one_gauge', line=22, status='calc', kind='num', printed='399', tol=0.0)
def check_2595():
    'drafted check, screened (runs; negative control fails). Book line 22, printed 399.'
    # Line 22: M = 399--411; M = E_sw / (k_B T_j)
    # Given: E_sw = (1.92--1.98) × 10^-18 J (lower end 1.92), T_j = 75°C = 348.15 K
    T_j_K = 75 + 273.15
    E_sw_low = 1.92e-18
    M_low = E_sw_low / (kB * T_j_K)
    value = M_low
    return locals()

@check(label='ch:onegauge:L22:411', chapter='ch:onegauge', part=7, title='drafted check, screened (runs; negative control fails) (tolerance: E_sw is printed to 3 figures)',
       file='part3/p3_08_one_gauge', line=22, status='calc', kind='num', printed='411', tol=0.0025)
def check_2596():
    'drafted check, screened (runs; negative control fails) (tolerance: E_sw is printed to 3 figures). Book line 22, printed 411.'
    # Line 22: M = E_sw / (k_B T_j)
    # Given: E_sw = (1.92--1.98) × 10^-18 J (upper end 1.98), T_j = 75°C = 348.15 K
    T_j_K = 75 + 273.15
    E_sw_high = 1.98e-18
    M_high = E_sw_high / (kB * T_j_K)
    value = M_high
    return locals()

@check(label='ch:onegauge:L22:0.0017', chapter='ch:onegauge', part=7, title='drafted check, screened (runs; negative control fails)',
       file='part3/p3_08_one_gauge', line=22, status='calc', kind='num', printed='0.0017', tol=0.0)
def check_2597():
    'drafted check, screened (runs; negative control fails). Book line 22, printed 0.0017.'
    # Line 22: Landauer floor = k_B T_j ln(2)
    # Line 38 confirms: Landauer floor k_B T_j ln(2) (9950X: 0.0017)
    # This is a dimensionless gauge reading: floor energy divided by E_sw
    T_j_K = 75 + 273.15
    E_sw_mid = 1.95e-18  # midpoint of 1.92--1.98
    landauer_floor_J = kB * T_j_K * LN2
    A_floor = landauer_floor_J / E_sw_mid
    value = A_floor
    return locals()

