@check(label='app:derivations:L194', chapter='app:derivations', part=8, title='same value as p2_03_theory:514 (least-squares CPL fit intercept w0)',
       file='appendices/app_C3_derivations', line=194, status='calc', kind='num', printed='-1.065', tol=0.00047)
def check_2780():
    'same value as p2_03_theory:514 (least-squares CPL fit intercept w0). Book line 194, printed -1.065.'
    Omc=0.315; OLc=1-Omc; bmc=Omc/2
    def w_eff(a): Ea=E_act(a); wi=-1-1/(3*a); return (-OLc+bmc*Ea*wi)/(OLc+bmc*Ea)
    avals=np.linspace(0.5,1,200); yvals=np.array([w_eff(a) for a in avals])
    Avec=np.vstack([np.ones_like(avals),1-avals]).T
    coef,_,_,_=np.linalg.lstsq(Avec,yvals,rcond=None)
    value=coef[0]
    return locals()

