@check(label='app:derivations:L340', chapter='app:derivations', part=8, title='drafted check, screened (runs; negative control fails)',
       file='appendices/app_C3_derivations', line=340, status='calc', kind='num', printed='2.2\\times10^{-10}', tol=0.0)
def check_2844():
    'drafted check, screened (runs; negative control fails). Book line 340, printed 2.2\\times10^{-10}.'
    # Mass at which tau_IAM = tau_DP: hbar * kB^2 * T^2 * ln(2) / E_G^3 = hbar / E_G
    # Simplifies to: kB^2 * T^2 * ln(2) / E_G^2 = 1, so E_G^2 = kB^2 * T^2 * ln(2)
    # E_G = kB * T * sqrt(ln(2))
    # With E_G = G m^2 / R and R = (3m / (4π rho))^(1/3):
    # G m^2 / (3m / (4π rho))^(1/3) = kB * T * sqrt(ln(2))
    # Solving for m: G m^2 / m^(1/3) = kB * T * sqrt(ln(2)) * (3/(4π rho))^(1/3)
    # G m^(5/3) = kB * T * sqrt(ln(2)) * (3/(4π rho))^(1/3)
    # m^(5/3) = (kB * T * sqrt(ln(2)) / G) * (3/(4π rho))^(1/3)
    rho_silica = 2200  # kg/m³
    T = 10e-3  # K, 10 mK
    m_equal = ((kB * T * np.sqrt(LN2) / G) * (3 / (4 * np.pi * rho_silica)) ** (1/3)) ** (3/5)
    value = m_equal
    return locals()

