@check(label='app:derivations:L348', chapter='app:derivations', part=8, title='drafted check, screened (runs; negative control fails)',
       file='appendices/app_C3_derivations', line=348, status='derived', kind='num', printed='0.414', tol=0.0)
def check_2849():
    'drafted check, screened (runs; negative control fails). Book line 348, printed 0.414.'
    # c = sqrt(2) - 1, where c is the coherence parameter at which S = 2 (line 348)
    # Derived from S = sqrt(2)(1 + c) = 2, so 1 + c = sqrt(2), c = sqrt(2) - 1
    c_value = np.sqrt(2) - 1
    value = round(c_value, 3)
    return locals()

@check(label='app:derivations:L348:0.586', chapter='app:derivations', part=8, title='drafted check, screened (runs; negative control fails)',
       file='appendices/app_C3_derivations', line=348, status='derived', kind='num', printed='0.586', tol=0.0)
def check_2850():
    'drafted check, screened (runs; negative control fails). Book line 348, printed 0.586.'
    # D = 1 - c at c = sqrt(2) - 1 (line 348, "D = 0.586")
    # D represents dephasing; D = 1 - c
    c_value = np.sqrt(2) - 1
    D_value = 1 - c_value
    value = round(D_value, 3)
    return locals()

@check(label='app:derivations:L349', chapter='app:derivations', part=8, title='drafted check, screened (runs; negative control fails)',
       file='appendices/app_C3_derivations', line=349, status='derived', kind='num', printed='1.87', tol=0.0)
def check_2851():
    'drafted check, screened (runs; negative control fails). Book line 349, printed 1.87.'
    # eta = t / tau_IAM at c = 1 - exp(-1/eta) = sqrt(2) - 1 (line 348-349)
    # Solve: 1 - exp(-1/eta) = sqrt(2) - 1
    # exp(-1/eta) = 2 - sqrt(2)
    # -1/eta = ln(2 - sqrt(2))
    # eta = -1 / ln(2 - sqrt(2))
    target_c = np.sqrt(2) - 1
    exp_arg = 1 - target_c  # = 2 - sqrt(2)
    eta_value = -1.0 / np.log(exp_arg)
    value = round(eta_value, 2)
    return locals()

